custom_css:
@import url('https://fonts.googleapis.com/css2?family=Blinker:wght@100;200;300;400;600;700;800;900&family=Inter:ital,opsz,wght@0,14..32,100..900;1,14..32,100..900&display=swap');

:root {
    --top-bar-bg: rgba(0, 0, 0, 0.2);
    --topBarBlockSize: 25px;
--font-body: "Inter", sans-serif;
--font-mono: "Blinker", sans-serif;
}

/* === Borders === */
#send_form,
.drawer-content,
.popup[open],
.menu_button,
.drawer-content select,
input,
.select2-container .select2-selection--multiple,
.inline-drawer-content,
textarea,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    border-radius: 0px !important;
}

/* === Buttons & Headers === */
.menu_button,
.buttons_block .menu_button {
    background: none !important;
    border: none !important;
    filter: brightness(0.5);
    transition: filter 0.2s ease;
}

.menu_button:hover {
    filter: brightness(0.9);
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background: rgba(0, 0, 0, 0.1);
    filter: brightness(0.7);
}

/* === Layout / Transparency === */
#right-nav-panel,
#left-nav-panel,
#top-bar {
    background-color: rgba(0, 0, 0, 0.7) !important;
}

.drawer-content {
    backdrop-filter: none !important;
}

.drawer-icon.closedIcon {
    opacity: 0.5;
}

#top-bar,
.drawer,
#top-settings-holder {
    height: var(--topBarBlockSize);
}

#extensionTopBar,
#extensionConnectionProfiles {
    border-radius: 0px !important;
}

/* === Tags === */
.tag {
    border-radius: 2px !important;
    padding: 2px 6px;
    font-size: 11px;
    letter-spacing: 0.04em;
    border: 1px solid rgba(255,255,255,0.12);
    box-shadow: inset 0 0 0 999px rgba(0,0,0,0.15);
    transition: all 0.15s ease;
}

.tag:hover {
    box-shadow: inset 0 0 0 999px rgba(0,0,0,0.05), 0 0 4px rgba(0,0,0,0.4);
    border-color: rgba(255,255,255,0.2);
}

.tag:active {
    transform: scale(0.96);
}

/* === World Info Cards === */
.world_entry {
    margin-bottom: 6px;
}

.wi-card-entry {
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: 2px !important;
    overflow: hidden;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.wi-card-entry:hover {
    border-color: rgba(255,255,255,0.18);
    box-shadow: 0 0 6px rgba(0,0,0,0.5);
}

.WIEntryTitleAndStatus textarea.text_pole {
    background: transparent;
    border: none;
    font-weight: 500;
    font-size: 13px;
    color: var(--SmartThemeMainTextColor);
}

.WIEntryTitleAndStatus textarea.text_pole:focus {
    outline: none;
    border-bottom: 1px solid var(--SmartThemeQuoteColor);
}

.inline-drawer-toggle {
    opacity: 0.5;
    transition: opacity 0.2s ease;
}

.inline-drawer-toggle:hover {
    opacity: 1;
}

/* ===== REASONING BLOCK ===== */

.mes_reasoning_header {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 6px;

    font-family: var(--font-body);
    font-size: 0.9em;
    letter-spacing: 0.3px;

    padding: 6px 20px;
}

/* main reasoning content */
.mes_reasoning {
    font-family: var(--font-mono);

    background: rgba(0,0,0,0.25);
    border: 1px solid rgba(255,255,255,0.06);
    border-top: none;

    border-radius: 0 0 6px 6px;
    padding: 10px 12px;

    font-size: 0.9em;
    line-height: 1.5;

    color: rgba(220, 235, 235, 0.85);
}

/* optional: subtle divider when collapsed/expanded */
.mes_reasoning_header + .mes_reasoning {
    margin-top: -1px;
}

/* optional: make code inside reasoning even cleaner */
.mes_reasoning code {
    background: rgba(255,255,255,0.04);
    border-radius: 4px;
    padding: 2px 4px;
}

/* === Toasts === */
.toast {
    background-color: rgba(18, 18, 20, 0.98) !important;
    color: rgba(245, 245, 245, 0.92) !important;
    border: 1px solid rgba(255, 255, 255, 0.14) !important;
    border-left: 4px solid rgba(255, 255, 255, 0.32) !important;
    border-radius: 10px !important;
    padding: 10px 12px !important;
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.4) !important;
    opacity: 1 !important;
}

.toast::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    background: linear-gradient(135deg, rgba(255,255,255,0.05), transparent 45%);
}

.toast > * {
    position: relative;
    z-index: 1;
}

.toast-title {
    font-weight: 650 !important;
    font-size: 12px !important;
    text-transform: uppercase !important;
    letter-spacing: 0.08em !important;
    color: rgba(255, 255, 255, 0.92) !important;
    margin: 0 0 6px 0 !important;
    padding: 0 0 6px 0 !important;
    border-bottom: 1px dashed rgba(255, 255, 255, 0.22) !important;
}

.toast-message {
    color: rgba(245, 245, 245, 0.88) !important;
    line-height: 1.4 !important;
    font-size: 13px !important;
    margin-left: 35px;
}

.toast.toast-success { border-left-color: rgba(90, 190, 150, 0.95) !important; }
.toast.toast-warning { border-left-color: rgba(245, 190, 70, 0.98) !important; }
.toast.toast-error { border-left-color: rgba(210, 80, 80, 0.98) !important; }

/* === Hover Effects === */
/* Smooth fade transition for characters, folders, personas, and recent chats */
.character_select, 
.bogus_folder_select,
.avatar-container,
.recentChat {
    transition: box-shadow 0.2s ease, background-color 0.2s ease !important;
}

/* Minimalist hover effect for all of them */
.character_select:hover, 
.bogus_folder_select:hover,
.avatar-container:hover,
.recentChat:hover {
    background-color: rgba(128, 128, 128, 0.05) !important;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.15) !important;
    border-radius: 8px !important;
}

/* === Favorite Char === */
.character_select.is_fav .avatar{ outline: 2px solid #96824e !important}

.character_select.is_fav .ch_name,
.character_select.is_fav:hover .ch_name {
    color: #96824e !important;
}

/* === QR === */
#qr--bar > .qr--buttons.qr--color{ background: transparent !important; }
